from taf.gnb.oam.coam.vdu.schemas.base.schema_common import SchemaObject, SchemaField


class PlanObjectV1(SchemaObject):
    className = SchemaField(name="class_name")
    distName = SchemaField(name="dist_name")
    version = SchemaField(name="version", optional=True)
    json_repr = SchemaField(name="payload", optional=True)

    def __init__(self, className, distName, json_repr, version):
        """
        :param className: NIDD class name of the object
        :param distName: NIDD dist name addr
        :param version: NIDD version
        :param json_repr: user plan id
        """
        self.className = className
        self.distName = distName
        self.version = version
        self.json_repr = json_repr

        super(PlanObjectV1, self).__init__()


class CurrentPlanInfoV1(SchemaObject):
    planId = SchemaField(name="plan_id")
    userPlanId = SchemaField(name="user_plan_id", optional=True)
    objects = SchemaField(name="objects", klass=PlanObjectV1, many=True)

    def __init__(self, planId, userPlanId, objects):
        """
        :param planId: Unique plan ID in scope of CU-OAM
        :param userPlanId: user plan id
        :param objects: list of NIDD objects
        """
        self.objects = objects
        self.planId = planId
        self.userPlanId = userPlanId

        super(CurrentPlanInfoV1, self).__init__()
